      love: '新戀情或全新的感情層次正在萌芽。單身者很可能遇到讓你心頭一暖、願意敞開心的人，這份心動來得真誠，不帶算計。有伴侶者，感情重新被灌溉，可能有告白、求婚、懷孕或更深的親密。你值得被愛，也有能力給出愛，讓這份感覺自然流動。',
