      love: '一則浪漫的訊息、一次溫柔的邀請或一份真誠的告白正在靠近。單身者可能遇到一位害羞、純真而溫柔的對象，互動中帶著小小的心動。有伴侶者，適合用小驚喜、小情書、小禮物表達愛意，浪漫從細節開始。',
