      finance: '可能有小小的好消息，例如來自創作或人情的收入。保持開放的心態，並用直覺感受機會，但仍要用實際數字確認。小額嘗試，慢慢累積信心。',
      health: '情緒柔軟敏感，適合透過藝術、音樂、水邊活動療癒身心。允許自己好奇、玩耍，會讓心情輕盈起來。留意不要過度敏感，必要時給自己一點空間。',
      relationship: '你溫柔親切，容易讓人放下防備，與人分享心事。適合結識新朋友，或收到暖心的消息。你的好奇與純真，是你最討人喜歡的特質。',
      advice: '今天安靜地問自己：「我現在心裡最想做的一件事是什麼？」不加評論地寫下第一個浮現的念頭，並為它做一個小小的行動。',
