      love: '感情迎來清醒與坦白。單身者終於看清自己想要的是什麼、不要的是什麼，不再將就。有伴侶者，適合把積壓的話攤開來說，誠實的溝通會讓關係重新有了方向。真話可能讓人緊張，但清楚的愛，比模糊的好更值得。',
